#include<bits/stdc++.h>
using namespace std;
int main(){
    int N;
    scanf("%d",&N);
    vector<int>par(N+1,0);
    vector<vector<int>>ch(N+1);
    for(int i=2;i<=N;i++){scanf("%d",&par[i]);ch[par[i]].push_back(i);}
    vector<bool>isLeaf(N+1,false);
    vector<int>leaves;
    for(int i=1;i<=N;i++)if(ch[i].empty()){isLeaf[i]=true;leaves.push_back(i);}
    int L=leaves.size();
    // For each node, compute leftmost and rightmost leaf index (in leaves array)
    vector<int>li(N+1,L),ri(N+1,-1);
    vector<int>leafIdx(N+1,-1);
    for(int i=0;i<L;i++) leafIdx[leaves[i]]=i;
    for(int v=N;v>=1;v--){
        if(isLeaf[v]) li[v]=ri[v]=leafIdx[v];
        for(int c:ch[v]){li[v]=min(li[v],li[c]);ri[v]=max(ri[v],ri[c]);}
    }
    // Build tree decomposition
    // Each internal node with children processes them left to right
    // maintaining a "current leaf" pointer that sweeps through the cycle
    vector<vector<int>>bags;
    vector<pair<int,int>>edges;
    auto addBag=[&](vector<int>b)->int{
        sort(b.begin(),b.end());
        b.erase(unique(b.begin(),b.end()),b.end());
        int id=bags.size();bags.push_back(b);return id;
    };
    // Returns (entry_bag, exit_bag) for subtree of v
    // entry_bag contains v and leaves[li[v]], exit_bag contains v and leaves[ri[v]]
    // All ancestors of v on path to root should be added by caller
    function<pair<int,int>(int,vector<int>&)> solve=[&](int v, vector<int>&anc)->pair<int,int>{
        anc.push_back(v);
        if(isLeaf[v]){
            int b=addBag(anc);
            anc.pop_back();
            return{b,b};
        }
        int k=ch[v].size();
        int firstBag=-1,lastBag=-1;
        for(int i=0;i<k;i++){
            int c=ch[v][i];
            auto[ce,cx]=solve(c,anc);
            if(i==0){
                firstBag=ce;
            } else {
                // bridge bag between previous child's exit and this child's entry
                auto bag=anc;
                bag.push_back(leaves[ri[ch[v][i-1]]]);
                bag.push_back(leaves[li[c]]);
                int br=addBag(bag);
                edges.push_back({lastBag,br});
                edges.push_back({br,ce});
            }
            if(i>0) lastBag=cx;
            else lastBag=cx;
            if(i==k-1) lastBag=cx;
        }
        anc.pop_back();
        return{firstBag,lastBag};
    };
    vector<int>anc;
    auto[e,x]=solve(1,anc);
    // Wrap-around edge: leaves[L-1] -> leaves[0]
    int wb=addBag({1,leaves[0],leaves[L-1]});
    edges.push_back({e,wb});
    edges.push_back({wb,x});
    int BN=bags.size();
    printf("%d\n",BN);
    for(int i=0;i<BN;i++){printf("%d",(int)bags[i].size());for(int x:bags[i])printf(" %d",x);printf("\n");}
    for(auto&[a,b]:edges) printf("%d %d\n",a+1,b+1);
}
